changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.test_id_shape_plan(p_shape text, p_tenant text, p_model text, p_id bigint, p_vec text)
RETURNS text LANGUAGE plpgsql AS $f$
DECLARE
    stmt constant text := 'SELECT chash FROM nexus.chunks WHERE tenant_id = %L AND embedding_model = %L AND collection_id = %s '
        || 'ORDER BY embedding_384 OPERATOR(nexus.<=>) %L::nexus.vector LIMIT 10';
    r record;
    plan text := '';
BEGIN
    PERFORM set_config('nexus.tenant', p_tenant, true);
    -- the test table is a few hundred rows, where a Seq Scan, a Bitmap Heap Scan and a Sort cost less than any HNSW scan. With those three off the only
    -- plan that orders by distance is an HNSW scan, so the plan shows WHICH HNSW index the planner reaches (the leaf's own, or the id-predicate
    -- partial one) and whether it can prove the statement implies the partial index's predicate: the question at production size
    PERFORM set_config('enable_seqscan', 'off', true);
    PERFORM set_config('enable_bitmapscan', 'off', true);
    PERFORM set_config('enable_sort', 'off', true);
    IF p_shape = 'a' THEN
        FOR r IN EXECUTE 'EXPLAIN (COSTS OFF) ' || format(stmt, p_tenant, p_model, p_id::text, p_vec) LOOP
            plan := plan || r."QUERY PLAN" || E'\n';
        END LOOP;
    ELSIF p_shape = 'b' THEN
        FOR r IN EXECUTE 'EXPLAIN (COSTS OFF) ' || format(stmt, p_tenant, p_model, p_id::text || '::bigint', p_vec) LOOP
            plan := plan || r."QUERY PLAN" || E'\n';
        END LOOP;
    ELSIF p_shape IN ('c', 'd') THEN
        EXECUTE format('SET LOCAL plan_cache_mode = %s', CASE p_shape WHEN 'c' THEN 'force_generic_plan' ELSE 'force_custom_plan' END);
        EXECUTE 'PREPARE test_id_shape (bigint) AS ' || format(stmt, p_tenant, p_model, '$1', p_vec);
        FOR r IN EXECUTE 'EXPLAIN (COSTS OFF) EXECUTE test_id_shape(' || p_id::text || ')' LOOP
            plan := plan || r."QUERY PLAN" || E'\n';
        END LOOP;
        EXECUTE 'DEALLOCATE test_id_shape';
    ELSE
        RAISE EXCEPTION 'unknown shape %', p_shape;
    END IF;
    RETURN plan;
END
$f$;

CREATE OR REPLACE FUNCTION nexus.test_id_shape_call(p_mode text, p_tenant text, p_model text, p_id bigint, p_vec text)
RETURNS bigint LANGUAGE plpgsql AS $f$
DECLARE
    n bigint;
BEGIN
    PERFORM set_config('nexus.tenant', p_tenant, true);
    -- the test table is a few hundred rows, where a Seq Scan, a Bitmap Heap Scan and a Sort cost less than any HNSW scan. With those three off the only
    -- plan that orders by distance is an HNSW scan, so the plan shows WHICH HNSW index the planner reaches (the leaf's own, or the id-predicate
    -- partial one) and whether it can prove the statement implies the partial index's predicate: the question at production size
    PERFORM set_config('enable_seqscan', 'off', true);
    PERFORM set_config('enable_bitmapscan', 'off', true);
    PERFORM set_config('enable_sort', 'off', true);
    IF p_mode = 'direct' THEN
        SELECT count(*) INTO n FROM (
            SELECT chash FROM nexus.chunks
            WHERE tenant_id = p_tenant AND embedding_model = p_model AND collection_id = p_id
            ORDER BY embedding_384 OPERATOR(nexus.<=>) p_vec::nexus.vector LIMIT 10) s;
    ELSE
        EXECUTE format('SELECT count(*) FROM (SELECT chash FROM nexus.chunks WHERE tenant_id = %L AND embedding_model = %L '
            || 'AND collection_id = %L ORDER BY embedding_384 OPERATOR(nexus.<=>) %L::nexus.vector LIMIT 10) s',
            p_tenant, p_model, p_id, p_vec) INTO n;
    END IF;
    PERFORM pg_stat_force_next_flush();
    RETURN n;
END
$f$;

GRANT EXECUTE ON FUNCTION nexus.test_id_shape_plan(text, text, text, bigint, text) TO ${svcRole};
GRANT EXECUTE ON FUNCTION nexus.test_id_shape_call(text, text, text, bigint, text) TO ${svcRole};

-- The planner needs the statistics of the rows the test just loaded; the changelog runs after them (runAlways).
ANALYZE nexus.chunks;
